CITY_SALARY_COEFF = {
    "北京市": 1.20, "上海市": 1.20, "深圳市": 1.20, "广州市": 1.10,
    "杭州市": 1.10, "南京市": 1.10, "成都市": 1.00, "武汉市": 1.00,
    "西安市": 1.00, "重庆市": 1.00,
    "贵阳市": 1.00, "遵义市": 1.00, "六盘水市": 0.90,
    "仁怀市": 0.95, "都匀市": 0.90, "凯里市": 0.90,
    # 其他三四线城市
    "天津市": 1.05, "苏州市": 1.05, "宁波市": 1.05, "青岛市": 1.00,
    "长沙市": 1.00, "郑州市": 1.00, "济南市": 1.00, "合肥市": 1.00,
    "厦门市": 1.05, "福州市": 1.00, "昆明市": 0.95, "南昌市": 0.95,
    "长春市": 0.95, "哈尔滨市": 0.95, "沈阳市": 0.95, "大连市": 1.00,
    "石家庄市": 0.95, "兰州市": 0.90, "乌鲁木齐市": 0.90,
    "海口市": 0.90, "拉萨市": 0.90, "西宁市": 0.90,
    "呼和浩特市": 0.90, "银川市": 0.90,
    "默认": 0.90,
}


def get_salary_coeff(city):
    return CITY_SALARY_COEFF.get(city, CITY_SALARY_COEFF["默认"])


def adjust_salary(sal_min, sal_max, coeff):
    """根据城市系数调整薪资，取整到百位"""
    return (int(sal_min * coeff / 100) * 100,
            int(sal_max * coeff / 100) * 100)


# ============================================================
# 福利项随机组合（按概率出现）
# ============================================================
BASE_BENEFITS = {
    # 五险一金类型（最常见）
    "basic": ["五险一金", "年度调薪"],
    # 额外福利池
    "bonus": ["年终奖", "项目奖金", "绩效奖金", "13薪", "年底双薪"],
    "allowance": ["驻厂补贴", "驻矿补贴", "野外补贴", "倒班补贴", "差旅补贴", "证书补贴", "通讯补贴", "住房补贴"],
    "welfare": ["年度旅游", "定期体检", "节日福利", "定期团建", "专业培训", "技能培训", "免费住宿", "免费工作餐", "免费班车"],
    "premium": ["六险一金", "六险二金", "股票期权"],
    "tech": ["弹性工作", "弹性打卡", "下午茶", "免费零食", "技术分享会"],
    "vacation": ["带薪年假", "寒暑假"],
    "career": ["晋升空间", "职称评定", "论文奖励"],
    "overseas": ["驻外机会", "驻外公寓", "国际会议"],
}


def random_benefits(industry, scale, nature, base_benefits_str):
    """根据公司规模/性质/行业，随机组合福利项"""
    items = []

    # 基础必含
    if "六险" in base_benefits_str:
        items.append("六险一金")
    elif "五险" in base_benefits_str:
        items.append("五险一金")

    items.append("年度调薪")

    rnd = random.random()

    # 大型/国企：更稳定福利
    if "10000人以上" in scale or "国有企业" in nature:
        items.append(random.choice(["年终奖", "项目奖金", "绩效奖金"]))
        if rnd > 0.4:
            items.append(random.choice(BASE_BENEFITS["welfare"]))
        if rnd > 0.6:
            items.append(random.choice(BASE_BENEFITS["allowance"]))
        if rnd > 0.7 and "野外" not in ",".join(items):
            items.append("定期培训")
        if "10000人以上" in scale and rnd > 0.5:
            items.append("住房补贴")

    # 上市公司/知名民企
    elif "民营企业" in nature and rnd > 0.5:
        items.append(random.choice(BASE_BENEFITS["bonus"]))
        if rnd > 0.4:
            items.append(random.choice(BASE_BENEFITS["welfare"]))
        if rnd > 0.6:
            items.append(random.choice(BASE_BENEFITS["tech"]))

    # 外资
    elif "外资" in nature:
        items.append("13薪")
        items.append("年度旅游")
        items.append("定期培训")

    # 普通中小企业
    else:
        if rnd > 0.5:
            items.append(random.choice(BASE_BENEFITS["welfare"]))
        if rnd > 0.6:
            items.append(random.choice(BASE_BENEFITS["allowance"]))

    # 互联网/高科技行业
    if any(k in industry for k in ["互联网", "AI", "软件", "IT", "云计算", "金融科技", "智能硬件"]):
        if rnd > 0.3:
            items.append("弹性工作")
        if rnd > 0.4:
            items.append("免费零食")
        if rnd > 0.5:
            items.append("年度旅游")
        if rnd > 0.6:
            items.append("技术分享会")
        if rnd > 0.7 and "六险" not in ",".join(items):
            items.append("六险一金")

    # 去重，保持顺序，限制总项数
    seen = set()
    result = []
    for item in items:
        if item not in seen:
            seen.add(item)
            result.append(item)

    # 总共不超过6项
    result = result[:6]
    return "、".join(result)


